onSubmit={(event) => {
        event.preventDefault();
        const next = new URLSearchParams(search);
        for (const [key, value] of [
            ["q", query],
            ["minPrice", minPrice],
            ["maxPrice", maxPrice],
        ]) {
            if (value)
                next.set(key, value);
            else
                next.delete(key);
        }
        next.set("page", "1");
        router.replace(`${pathname}?${next.toString()}`, { scroll: false });
    }}
